using System;
using System.Drawing;
using System.Windows.Forms;
namespace ImageNdi {
public class CountdownSettings {
 public int YellowSeconds{get;set;}public int RedSeconds{get;set;}public int GreenArgb{get;set;}public int YellowArgb{get;set;}public int RedArgb{get;set;}public int LoopArgb{get;set;}
 public CountdownSettings(){YellowSeconds=30;RedSeconds=10;GreenArgb=Color.LimeGreen.ToArgb();YellowArgb=Color.Yellow.ToArgb();RedArgb=Color.Red.ToArgb();LoopArgb=Color.Orange.ToArgb();}
 public void Validate(){if(YellowSeconds<1||YellowSeconds>86400||RedSeconds<0||RedSeconds>=YellowSeconds)throw new ArgumentException("La soglia gialla deve essere maggiore di quella rossa (da 1 a 86400 secondi).");foreach(int value in new[]{GreenArgb,YellowArgb,RedArgb,LoopArgb})if(Color.FromArgb(value).A!=255)throw new ArgumentException("I colori del countdown devono essere opachi.");}
 public Color ColorFor(double remaining,bool loop=false){if(loop)return Color.FromArgb(LoopArgb);return Color.FromArgb(remaining<=RedSeconds?RedArgb:remaining<=YellowSeconds?YellowArgb:GreenArgb);}
}
public partial class MainWindow {
 NumericUpDown countdownYellow,countdownRed;Button countdownGreenColor,countdownYellowColor,countdownRedColor,countdownLoopColor;
 static Color CountdownButtonText(Color value){return value.R*.299+value.G*.587+value.B*.114>128?Color.Black:Color.White;}
 static Button CountdownColorButton(string text,int argb){var button=new Button{Text=text,AutoSize=true,BackColor=Color.FromArgb(argb)};button.Click+=delegate{using(var picker=new ColorDialog{Color=button.BackColor,FullOpen=true})if(picker.ShowDialog(button.FindForm())==DialogResult.OK){button.BackColor=picker.Color;button.ForeColor=CountdownButtonText(picker.Color);}};return button;}
 TabPage CreateCountdownSettingsPage(){var page=new TabPage("Countdown");var panel=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(16),AutoScroll=true};panel.Controls.Add(new Label{Text="Colori a soglie per i video senza loop; colore fisso per i video in loop.",AutoSize=true});countdownYellow=Number(1,86400,30);countdownYellow.Name="CountdownYellowSeconds";countdownRed=Number(0,86399,10);countdownRed.Name="CountdownRedSeconds";ShellField(panel,"Giallo da (secondi rimanenti)",countdownYellow);ShellField(panel,"Rosso da (secondi rimanenti)",countdownRed);var colors=ShellRow();colors.Dock=DockStyle.None;colors.AutoSize=true;colors.AutoSizeMode=AutoSizeMode.GrowAndShrink;countdownGreenColor=CountdownColorButton("Colore sopra soglia gialla",settings.Countdown.GreenArgb);countdownYellowColor=CountdownColorButton("Colore fascia gialla",settings.Countdown.YellowArgb);countdownRedColor=CountdownColorButton("Colore fascia rossa",settings.Countdown.RedArgb);colors.Controls.Add(countdownGreenColor);colors.Controls.Add(countdownYellowColor);colors.Controls.Add(countdownRedColor);panel.Controls.Add(colors);countdownLoopColor=CountdownColorButton("Colore fisso Loop",settings.Countdown.LoopArgb);panel.Controls.Add(countdownLoopColor);panel.Controls.Add(new Label{Text="Con i valori predefiniti: verde sopra 30 s, giallo da 30 a oltre 10 s, rosso da 10 a 0 s.\r\nLoop: colore fisso arancione, personalizzabile. Il video terminato senza loop resta rosso.",AutoSize=true,MaximumSize=new Size(660,0)});AddButton(panel,"Applica countdown",delegate{try{var value=new CountdownSettings{YellowSeconds=(int)countdownYellow.Value,RedSeconds=(int)countdownRed.Value,GreenArgb=countdownGreenColor.BackColor.ToArgb(),YellowArgb=countdownYellowColor.BackColor.ToArgb(),RedArgb=countdownRedColor.BackColor.ToArgb(),LoopArgb=countdownLoopColor.BackColor.ToArgb()};value.Validate();settings.Countdown=value;UpdateProgramCountdown();Save();}catch(Exception e){MessageBox.Show(e.Message,"Countdown");}});AddButton(panel,"Ripristina valori predefiniti",delegate{SetCountdownEditor(new CountdownSettings());});page.Controls.Add(panel);LoadCountdownEditor();return page;}
 void SetCountdownEditor(CountdownSettings value){if(countdownYellow==null)return;countdownYellow.Value=value.YellowSeconds;countdownRed.Value=value.RedSeconds;var buttons=new[]{countdownGreenColor,countdownYellowColor,countdownRedColor,countdownLoopColor};var values=new[]{value.GreenArgb,value.YellowArgb,value.RedArgb,value.LoopArgb};for(int i=0;i<buttons.Length;i++){buttons[i].BackColor=Color.FromArgb(values[i]);buttons[i].ForeColor=CountdownButtonText(buttons[i].BackColor);}}
 void LoadCountdownEditor(){SetCountdownEditor(settings.Countdown);}
}
}
